// @ts-check
// Something the porter can use: a door, a staircase, an object to look at, an item to pick up, a person to talk to. Put this
// behaviour (and a Collider3D, so a click or a tap can hit it) on the entity and tag it "interactable"; scripts/porter.js
// finds the nearest one in reach, shows its prompt, highlights it and calls interact() when the player presses the button,
// clicks it, taps it or walks to it by click.
//
// Props (the scene sets them, scenes/*.scene.json are generated by assets/src/build_lodge.py):
//   kind          "door" | "area" | "examine" | "item" | "talk" | "puzzle"; a door that has a `requiresItem`/`requiresFlag` is locked
//   name          locale key of the object's name, shown in the prompt ("object.library_door")
//   verb          locale key of the verb; default by kind (interact.verb.open / enter / examine / take / talk)
//   point         [x, z] where the object is used from (default: the entity's position)
//   reach         metres from `point` the porter may stand at (default 1.7)
//   text          examine: locale key of the line shown
//   item          item: the item id (data/items.json) put in the inventory;  once: story flag set when it was taken
//   area, arrive  area: the area to go to (scripts/area.js AREAS) and the spawn entity id there
//   requiresItem  door: item id that unlocks it;  requiresFlag: story flag that unlocks it;  lockedText: line shown when locked
//   dialogue      talk: the dialogue id (scripts/dialogue.js)
//   puzzle        puzzle: the puzzle id (scripts/puzzles.js: "drawer", "timetable", "fuse"); the screen opens, or a line says why not
//
// A door that is opened (the flag "open.<id>") is open for the rest of the game: it loses its collider and its prompt.
import { Behaviour, world, i18n } from "factoria";
import { EVENTS, emit } from "./events.js";
import * as story from "./story.js";
import * as items from "./items.js";
import * as dialogue from "./dialogue.js";
import * as puzzles from "./puzzles.js";

const VERBS = { door: "interact.verb.open", area: "interact.verb.enter", examine: "interact.verb.examine", item: "interact.verb.take", talk: "interact.verb.talk", puzzle: "interact.verb.examine" };

export default class Interactable extends Behaviour {
  kind = "examine";
  name = "";
  verb = "";
  point = null;
  reach = 1.7;
  text = "";
  item = "";
  once = "";
  area = "";
  arrive = "spawn_default";
  requiresItem = "";
  requiresFlag = "";
  lockedText = "";
  dialogue = "";
  puzzle = "";
  /** Colour of the highlight (added to the surface as emission). */
  glow = [0.34, 0.26, 0.1, 1];

  onStart() {
    this.highlighted = false;
    this.phase = 0;
    this.used = 0;
    this.mesh = this.entity.get("MeshRenderer");
    if (this.kind === "door" && story.has("open." + this.entity.id)) this.setOpen();
    if (this.kind === "item" && this.taken) this.showTaken();
  }

  /** The point the porter is measured from: the `point` prop, else the entity's position, as [x, z]. */
  get spot() {
    if (this.point) return [this.point[0], this.point[1]];
    const p = this.entity.worldPosition;
    return [p.x, p.z];
  }

  /** True once the item of an item box was taken. */
  get taken() {
    return this.once !== "" && story.has(this.once);
  }

  /** True when the door was opened (now or in an earlier visit). */
  get isOpen() {
    return this.kind === "door" && story.has("open." + this.entity.id);
  }

  /** Whether the porter can use it now: an opened door and an emptied box have nothing left to do. */
  get available() {
    if (this.kind === "door") return !this.isOpen;
    if (this.kind === "item") return !this.taken;
    return true;
  }

  /** What stops the door from opening, or "" when nothing does: the item id or flag name it needs. */
  get missing() {
    if (this.kind !== "door") return "";
    if (this.requiresItem && !items.has(this.requiresItem)) return this.requiresItem;
    if (this.requiresFlag && !story.has(this.requiresFlag)) return this.requiresFlag;
    return "";
  }

  /** The locale key of the verb the prompt shows. */
  verbKey() {
    return this.verb || VERBS[this.kind] || VERBS.examine;
  }

  /** The prompt's object name (translated). */
  displayName() {
    return this.name ? i18n.t(this.name) : "";
  }

  /** Turns the highlight (a slow pulse of emission) on or off. */
  setHighlight(on) {
    if (on === this.highlighted) return;
    this.highlighted = on;
    this.phase = 0;
    if (!on && this.mesh) this.mesh.emissive = [0, 0, 0, 1];
  }

  onUpdate(dt) {
    if (!this.highlighted || !this.mesh) return;
    this.phase += dt * 3.2;
    const k = 0.65 + 0.35 * Math.sin(this.phase);
    this.mesh.emissive = [this.glow[0] * k, this.glow[1] * k, this.glow[2] * k, 1];
  }

  /**
   * Uses the object. `hud` is the HUD behaviour (for the message line), `areas` the area controller (for stairs and doors that
   * change area). Returns { ok, kind, id, message } and sends EVENTS.interacted.
   */
  interact() {
    const hud = world.find("hud")?.behaviour;
    const areas = world.find("area")?.behaviour;
    const id = this.entity.id;
    let ok = true;
    let message = "";
    switch (this.kind) {
      case "door": {
        const missing = this.missing;
        if (missing) {
          ok = false;
          message = this.lockedText || "door.locked";
          emit(EVENTS.doorLocked, { id, requires: missing, text: message });
        } else {
          story.set("open." + id);
          this.setOpen();
          emit(EVENTS.doorOpened, { id });
          message = "door.opened";
        }
        break;
      }
      case "area":
        ok = !!areas && areas.goTo(this.area, this.arrive);
        break;
      case "examine":
        message = this.text || "examine.nothing";
        story.inc("examined." + id);
        break;
      case "item":
        if (this.taken) {
          ok = false;
          break;
        }
        items.add(this.item, id);
        if (this.once) story.set(this.once);
        this.showTaken();
        message = "item.taken";
        break;
      case "puzzle": {
        const av = puzzles.availability(this.puzzle);
        const screens = world.find("screens")?.behaviour;
        if (!av.ok) {
          ok = false;
          message = av.key;
        } else if (puzzles.solved(this.puzzle)) {
          message = `puzzle.${this.puzzle}.done`;
        } else {
          ok = !!screens && screens.openPuzzle(this.puzzle);
        }
        break;
      }
      case "talk":
        ok = dialogue.start(this.dialogue, { speaker: id }).started;
        break;
      default:
        ok = false;
    }
    if (hud && message) {
      const def = this.kind === "item" ? items.get(this.item) : null;
      hud.say(message, def ? { name: i18n.t(def.nameKey) } : { name: this.displayName() });
    }
    this.used++;
    emit(EVENTS.interacted, { id, kind: this.kind, name: this.name, ok });
    this.setHighlight(false);
    return { ok, kind: this.kind, id, message };
  }

  /** A door that opens: the open leaf replaces the shut one and the collider goes (the NavMesh3D learns it at once). */
  setOpen() {
    if (this.mesh) this.mesh.mesh = "assets/models/lodge/doorwayOpen.glb";
    if (this.entity.has("Collider3D")) this.entity.remove("Collider3D");
    this.setHighlight(false);
  }

  /** An item box that was emptied: the open box replaces the closed one. */
  showTaken() {
    if (this.mesh) this.mesh.mesh = "assets/models/lodge/cardboardBoxOpen.glb";
    this.setHighlight(false);
  }
}
